import {parseWorkspaceBackup} from './core.js';
const aad = new TextEncoder().encode('ascend-sync-v1');
export const b64 = bytes => {let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s);};
export const unb64 = s => Uint8Array.from(atob(s.replace(/\s/g,'')),c=>c.charCodeAt(0));
export const newSyncKey = () => b64(crypto.getRandomValues(new Uint8Array(32)));
export function canonical(value) {if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).filter(k=>value[k]!==undefined&&k!=='exportedAt').sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';return JSON.stringify(value);}
export async function fingerprint(workspace) {return b64(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(workspace)))));}
export function validateConnection(c) {if(!c||!c.token||typeof c.token!=='string'||!/^[-a-zA-Z0-9_]+$/.test(c.owner||'')||!/^[-a-zA-Z0-9_.]+$/.test(c.repo||'')||c.repo==='.'||c.repo==='..')throw Error('Enter a valid GitHub owner, private repository, and token.');try{if(unb64(c.key||'').length!==32)throw 0;}catch{throw Error('The sync key must be a 32-byte Base64 key. Import the connection from your first device.');}return c;}
export async function sealWorkspace(workspace,key) {const bytes=new TextEncoder().encode(JSON.stringify({workspace,modifiedAt:new Date().toISOString()}));const iv=crypto.getRandomValues(new Uint8Array(12));const k=await crypto.subtle.importKey('raw',unb64(key),'AES-GCM',false,['encrypt']);const encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad,tagLength:128},k,bytes));const combined=new Uint8Array(12+encrypted.length);combined.set(iv);combined.set(encrypted,12);return JSON.stringify({format:'ascend.encrypted.v1',data:b64(combined)});}
export async function openWorkspace(text,key) {if(typeof text!=='string'||text.length>24*1024*1024)throw Error('Sync file is too large.');let value;try{const env=JSON.parse(text);if(env.format!=='ascend.encrypted.v1')throw 0;const bytes=unb64(env.data);if(bytes.length<28)throw 0;const k=await crypto.subtle.importKey('raw',unb64(key),'AES-GCM',false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(0,12),additionalData:aad,tagLength:128},k,bytes.slice(12));value=JSON.parse(new TextDecoder().decode(plain));}catch{throw Error('The sync file could not be decrypted. Use the connection/key from your first device.');}return parseWorkspaceBackup(JSON.stringify(value.workspace));}
export function syncDecision(localHash,remoteHash,baseline) {if(localHash===remoteHash)return 'same';if(!baseline)return 'conflict';if(localHash===baseline)return 'pull';if(remoteHash===baseline)return 'push';return 'conflict';}
export class GitHubFile {
 constructor(config,transport=fetch){this.config=validateConnection(config);this.transport=transport.bind(globalThis);this.base=`https://api.github.com/repos/${encodeURIComponent(config.owner)}/${encodeURIComponent(config.repo)}`;}
 async request(path,options={}) {const response=await this.transport(this.base+path,{...options,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${this.config.token}`,'X-GitHub-Api-Version':'2022-11-28',...options.headers},signal:AbortSignal.timeout(30000)});if(!response.ok&&response.status!==404){const error=Error(response.status===409||response.status===422?'The cloud file changed. Sync again and review both versions.':response.status===401||response.status===403?'GitHub rejected the token. Check its expiry and Contents read/write permission.':`GitHub sync failed (${response.status}).`);error.status=response.status;throw error;}return response;}
 async verify(){const response=await this.request('');if(response.status===404)throw Error('The repository is unavailable to this token.');const repo=await response.json();if(!repo.private)throw Error('Sync requires a private repository.');}
 async read(){const response=await this.request('/contents/workspace.enc.json');if(response.status===404)return null;const value=await response.json();if(value.size>24*1024*1024)throw Error('Sync file exceeds the safety limit.');const text=value.encoding==='base64'?new TextDecoder().decode(unb64(value.content)):await (await this.request('/contents/workspace.enc.json',{headers:{Accept:'application/vnd.github.raw+json'}})).text();return {sha:value.sha,workspace:await openWorkspace(text,this.config.key)};}
 async write(workspace,sha){const envelope=await sealWorkspace(workspace,this.config.key);const response=await this.request('/contents/workspace.enc.json',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:'Update encrypted Ascend workspace',content:b64(new TextEncoder().encode(envelope)),...(sha?{sha}:{})})});if(response.status===404)throw Error('The repository is unavailable or Contents write permission is missing.');return (await response.json()).content.sha;}
}
